pub fn insert_before(&mut self, index: Index<T>, value: T) -> Index<T> {
    let entry = self.entries.get(index.index()).expect("Invalid index");
    match entry {
        Entry::Occupied(entry) if entry.generation == index.generation => {
            let previous_index = entry.previous;
            let new_index = self.insert_new(value, previous_index, Some(index.index().into()));
            if let Some(prev_index) = previous_index {
                self.entries[prev_index.get()].occupied_mut().next = Some(new_index);
            }
            entry.previous = Some(new_index);
            Index::new(new_index, self.generation)
        }
        _ => panic!("Invalid index"),
    }
}

